func (s *Server) handlePageTabsGET(w http.ResponseWriter, r *http.Request) {

	// Mint the per-instance identifier for this page load.
	// The client echoes this value on action requests and on the SSE
	// stream connect via the Datapages-Instance header.
	instanceID, err := s.signStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// The page carries an identifier that stands for one tab's state.
	// A cache that hands it to a second visitor hands over the state.
	w.Header().Set("Cache-Control", "no-store")

	p := app.PageTabs{
		App: s.app,
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageTabs.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)
	}

	bodySuffix := func(w http.ResponseWriter) {
	}

	if err := s.writeHTML(
		w, r, datapages.Session[struct{}]{}, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageTabs", err)
		return
	}
}

func (s *Server) handlePageTabsGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	if sess.UserID() == "" {
		// The query carries the signals a stream subscribes by,
		// which the anonymous route needs as much as this one.
		target := r.URL.Path + "/anon"
		if r.URL.RawQuery != "" {
			target += "?" + r.URL.RawQuery
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
		return
	}
	if !s.checkUserSubject(w, sess.UserID()) {
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupStateTab(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	var slot *stateSlotStateTab

	p := app.PageTabs{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageTabs(sess.UserID()),
		func(
			streamID datapages.StreamID,
			sse *datastar.ServerSentEventGenerator,
		) error {
			slot = s.allocateStateTab(instanceID)
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			// The close hook is wired up only once this one has returned nil.
			// An open that ends any other way gives the instance back here,
			// since nothing else is left to do it.
			opened := false
			defer func() {
				if !opened {
					s.releaseStateTab(instanceID, slot)
				}
			}()
			slot.mu.Lock()
			defer slot.mu.Unlock()
			if err := p.StreamOpen(r, streamID, slot.state); err != nil {
				return err
			}
			opened = true
			return nil
		},
		func(streamID datapages.StreamID) {
			s.releaseStateTab(instanceID, slot)
		},
		func(
			streamID datapages.StreamID,
			sse *datastar.ServerSentEventGenerator, ch <-chan messaging.Message,
		) {
			var eventTicked app.EventTicked
			var eventNoticed app.EventNoticed
			for msg := range ch {
				switch {
				case msg.Subject == EvSubjTicked:
					eventTicked = app.EventTicked{}
					if err := json.Unmarshal(msg.Data, &eventTicked); err != nil {
						s.LogErr("unmarshaling EventTicked JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnTicked(eventTicked, dpsse.New(sse), slot.state); err != nil {
						s.LogErr("handling PageTabs.OnTicked", err)
					}
					slot.mu.Unlock()
				case strings.HasPrefix(msg.Subject, EvSubjPrefNoticed):
					eventNoticed = app.EventNoticed{}
					if err := json.Unmarshal(msg.Data, &eventNoticed); err != nil {
						s.LogErr("unmarshaling EventNoticed JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnNoticed(eventNoticed, dpsse.New(sse), slot.state); err != nil {
						s.LogErr("handling PageTabs.OnNoticed", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

